  function $(s, r) { return (r || document).querySelector(s); }
  function $$(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); }
  function esc(s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;"); }
  function fillBooks(sel, chapSel) {
    if (!sel) return;
    sel.innerHTML = BOOKS.map(function (b) { return '<option value="' + b[0] + '">' + b[0] + "</option>"; }).join("");
    function fillCh() {
      var n = 0; BOOKS.forEach(function (b) { if (b[0] === sel.value) n = b[1]; });
      var out = ""; for (var i = 1; i <= n; i++) out += "<option>" + i + "</option>";
      if (chapSel) chapSel.innerHTML = out;
    }
    sel.addEventListener("change", fillCh); fillCh();
  }
  function epNumber(book, ch) {
    var ep = 0;
    for (var i = 0; i < BOOKS.length; i++) {
      if (BOOKS[i][0] === book) return ep + Number(ch);
      ep += BOOKS[i][1];
    }
    return 0;
  }
  function fromEp(ep) {
    var acc = 0;
    for (var i = 0; i < BOOKS.length; i++) {
      if (ep <= acc + BOOKS[i][1]) return { book: BOOKS[i][0], chapter: ep - acc };
      acc += BOOKS[i][1];
    }
    return null;
  }
  function chapInfo(book, ch) { return CHAPTERS[book + " " + ch] || null; }
  function showResult(html) {
    var box = $("#tool-result");
    box.innerHTML = html + '<p class="tool-printrow"><button type="button" class="tool-submit" onclick="window.print()">Print / save my result</button></p>';
    box.hidden = false; box.scrollIntoView({ behavior: "smooth", block: "start" });
  }
  function sendIntake(tool, data) {
    try {
      var key = "trw_tool_" + tool;
      var arr = JSON.parse(localStorage.getItem(key) || "[]"); arr.push(data);
      localStorage.setItem(key, JSON.stringify(arr));
    } catch (e) {}
    if (typeof INTAKE_ENDPOINT !== "undefined" && INTAKE_ENDPOINT) {
      // Fleet bookings spine (POST /api/lead — the same intake the other
      // fleet sites post to): site + name + email at the top level, the
      // tool's own inputs carried in notes. Email-first site: no phone.
      var notes = "Free tool: " + tool;
      try {
        var rest = {};
        for (var k in data) { if (k !== "name" && k !== "email") rest[k] = data[k]; }
        notes += " \u2014 inputs: " + JSON.stringify(rest);
      } catch (e) {}
      try {
        fetch(INTAKE_ENDPOINT, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            site: "therightway.life",
            name: data.name || "",
            email: data.email || "",
            division: "therightway",
            notes: notes
          })
        });
      } catch (e) {}
    }
  }
  function formData(form) {
    var d = {}; var fd = new FormData(form);
    fd.forEach(function (v, k) { if (d[k]) { d[k] = [].concat(d[k], v); } else d[k] = v; });
    return d;
  }

